mapper.delete:
DELETE FROM mos_peak_bepf_data
WHERE aggregator_id = #{aggregatorId}
AND source_id = #{sourceId}
AND data_time >= #{startDate}
AND data_time <= #{endDate}

mapper.select:
SELECT * FROM mos_peak_bepf_data
WHERE aggregator_id = #{aggregatorId}
AND source_id = #{sourceId}
AND data_time > #{dataTime}
AND data_time <= DATE_ADD(#{dataTime}, INTERVAL 1 DAY)
ORDER BY point_index ASC
